extern "C" {
/* Generated by port/fast3d/hd_texture_scope_embed.cmake from port/fast3d/texture_packs. */
extern const unsigned char hd_level_sources_json[];
extern const size_t hd_level_sources_json_size;
extern const unsigned char hd_level_native_aliases_json[];
extern const size_t hd_level_native_aliases_json_size;
extern const unsigned char hd_dam_native_aliases_json[];
extern const size_t hd_dam_native_aliases_json_size;
}

namespace {
constexpr unsigned kCheckFrames = 300;  /* look for an added or removed pack about every 5 s */

std::atomic<int> g_requested{1};
std::atomic<int> g_found{-1};           /* keys found by the last search; -1 before one */
std::atomic<int> g_custom{-1};          /* of those, keys from custom packs */
std::string g_root;
int g_current = -1;
unsigned g_frames = 0;
std::string g_signature;
hd_textures::Pack g_pack;
std::set<hd_textures::Key> g_reported;

/* Custom-pack images read off the render thread. Two workers keep a
 * level's first frames moving while the artist's masters are inflated
 * (about 100 ms each at 2048 px). */
constexpr int kWorkers = 2;
struct Job {
    uint32_t request = 0, generation = 0;
    hd_textures::Key key;
    hd_textures::Entry entry;   /* a copy: the index may be rebuilt meanwhile */
    unsigned width = 0, height = 0;
};
struct Done {
    uint32_t request = 0, generation = 0;
    hd_textures::Image image;
};
struct Workers {
    std::mutex lock;
    std::condition_variable wake;
    std::deque<Job> jobs;
    std::deque<Done> done;
    std::set<hd_textures::Key> reported;
    bool started = false;
};
/* Never destroyed: detached workers may still run while the process exits. */
Workers &workers() {
    static Workers *w = new Workers;
    return *w;
}
std::atomic<uint32_t> g_generation{0};  /* bumped whenever the index is rebuilt */
uint32_t g_next_request = 0;

/* Same shape, at least the native size: anything else keeps the original. */
bool usable(const hd_textures::Entry &entry, unsigned width, unsigned height, hd_textures::Image &image) {
    if (!hd_textures::Pack::read(entry, image) || uint64_t(image.width) * height != uint64_t(image.height) * width
        || image.width < width) {
        image = hd_textures::Image{};
        return false;
    }
    return true;
}

void work() {
    Workers &w = workers();
    for (;;) {
        Job job;
        {
            std::unique_lock<std::mutex> guard(w.lock);
            w.wake.wait(guard, [&] { return !w.jobs.empty(); });
            job = std::move(w.jobs.front());
            w.jobs.pop_front();
        }
        if (job.generation != g_generation.load()) continue;
        hd_textures::Image image;
        bool ok = false;
        try {
            ok = usable(job.entry, job.width, job.height, image);
            if (ok && image.width > job.width * hd_textures::kMaxScale) {
                image = hd_textures::resample(image, job.width * hd_textures::kMaxScale,
                                              job.height * hd_textures::kMaxScale);
            }
        } catch (const std::bad_alloc &) {
            /* A 4096 px master needs about 100 MB while it is read; in the
             * 32-bit Windows build's address space that can fail. */
            ok = false;
            image = hd_textures::Image{};
        }
        std::lock_guard<std::mutex> guard(w.lock);
        if (ok && !image.rgba.empty()) {
            w.done.push_back({job.request, job.generation, std::move(image)});
        } else if (w.reported.insert(job.key).second) {
            std::fprintf(stderr, "hd: unusable image for %08X in %s; original kept\n", job.key.texture,
                         job.entry.file.string().c_str());
        }
    }
}

std::string text(const unsigned char *data, size_t size) {
    return std::string(reinterpret_cast<const char *>(data), size);
}

/* The HUD ammo icons' art in the pack, by slot: the visible size of the
 * game's icon and the pack key of its image (from the pack's UI/Ammo folder;
 * the tank shell's six palette copies are one image). */
struct AmmoArt {
    unsigned width, height;
    hd_textures::Key key;
};
const AmmoArt kAmmo[hd_textures::kAmmoSlots] = {
    {5, 12, {0xAF0A1953, 0, 0, 3}},   /* 9 mm */
    {5, 28, {0xAC193F4F, 0, 0, 3}},   /* rifle */
    {6, 20, {0x2B351868, 0, 0, 3}},   /* shotgun */
    {6, 24, {0x98685E98, 0, 0, 3}},   /* throwing knife */
    {8, 21, {0xEC11BEAB, 0, 0, 3}},   /* grenade launcher */
    {7, 22, {0xBA97A223, 0, 0, 3}},   /* rocket */
    {0, 0, {0, 0, 0, 0}},             /* plain mine: no HD art */
    {14, 18, {0xAF8E57EF, 0, 0, 3}},  /* grenade */
    {5, 15, {0x91651507, 0, 0, 3}},   /* magnum */
    {5, 12, {0xFA82F840, 0, 0, 3}},   /* golden gun */
    {14, 14, {0x551F375D, 0, 0, 3}},  /* remote mine */
    {14, 14, {0x6F1AC5BE, 0, 0, 3}},  /* timed mine */
    {14, 14, {0x8640BBB3, 0, 0, 3}},  /* proximity mine */
    {7, 22, {0x0590F622, 0, 2, 1}},   /* tank shell */
};

const hd_textures::Scope &scope() {
    static hd_textures::Scope s;
    static bool loaded = false;
    if (!loaded) {
        loaded = true;
        if (!hd_textures::parse_scope(text(hd_level_sources_json, hd_level_sources_json_size),
                                      {text(hd_level_native_aliases_json, hd_level_native_aliases_json_size),
                                       text(hd_dam_native_aliases_json, hd_dam_native_aliases_json_size)},
                                      s)) {
            std::fprintf(stderr, "hd: the texture scope could not be read; original textures stay\n");
        }
        for (const AmmoArt &art : kAmmo) {
            if (art.width) s.keys.insert(art.key);  /* indexed, found by slot rather than by tile */
        }
    }
    return s;
}

/* Every file under the pack folder (paths, sizes, times), to notice a pack
 * being added, replaced, removed or edited - loose PNGs of a pack being made
 * included - without reading any of them. The directory entries carry these
 * from the listing itself, so a pack of a few thousand files costs a few ms. */
std::string signature() {
    std::string out;
    std::error_code error;
    const auto options = std::filesystem::directory_options::skip_permission_denied;
    for (auto it = std::filesystem::recursive_directory_iterator(g_root, options, error);
         !error && it != std::filesystem::recursive_directory_iterator(); it.increment(error)) {
        std::error_code e;
        out += it->path().generic_string();
        out += '|';
        if (it->is_regular_file(e)) out += std::to_string(it->file_size(e));
        out += '|';
        out += std::to_string(it->last_write_time(e).time_since_epoch().count());
        out += '\n';
    }
    return out;
}

/* The files the HD Textures page downloads: the checked release ZIP and the
 * Egyptian PNGs, kept to the reviewed environment scope. Anything else in the
 * folder is a player's own pack. */
bool downloaded(const std::filesystem::path &file) {
    int count = 0;
    const auto *list = hd_download::pack_files(count);
    const auto normal = file.lexically_normal();
    for (int i = 0; i < count; i++) {
        if (hd_download::path_of(g_root, list[i]).lexically_normal() == normal) return true;
    }
    return false;
}
}  // namespace

extern "C" void portTexturePackRoot(const char *root) { g_root = root ? root : ""; }
extern "C" int portTexturePackCustomCount(void) { return g_custom.load(); }
extern "C" const char *portTexturePackFolder(void) {
    std::error_code error;
    if (!g_root.empty()) std::filesystem::create_directories(std::filesystem::path(g_root), error);
    return g_root.c_str();
}
extern "C" void portTexturePackSet(int mode) { g_requested.store(mode ? 1 : 0); }
extern "C" int portTexturePackGet(void) { return g_requested.load(); }
extern "C" const char *portTexturePackValueText(const char *text) {
    if (g_found.load() != 0) return text;
    return portHdTexturesState() == PORT_HDTEX_UNSUPPORTED ? "HD (not found)\n" : "HD (Get)\n";
}

namespace hd_textures {
bool beginFrame() {
    const int mode = g_requested.load();
    const bool changed = mode != g_current;
    if (!changed && (!mode || ++g_frames % kCheckFrames != 0)) return false;
    std::string now = mode && !g_root.empty() ? signature() : std::string();
    if (!changed && now == g_signature) return false;
    g_current = mode;
    g_signature = now;
    g_pack.clear();
    g_reported.clear();
    g_custom.store(-1);
    g_generation++;
    {
        Workers &w = workers();
        std::lock_guard<std::mutex> guard(w.lock);
        w.jobs.clear();
        w.done.clear();
        w.reported.clear();
    }
    if (mode && !g_root.empty()) {
        const size_t found = g_pack.index(std::filesystem::path(g_root), scope(), downloaded);
        g_found.store(int(found));
        g_custom.store(int(g_pack.custom()));
        if (found) {
            std::fprintf(stderr, "hd: %zu textures in %s (%zu from custom packs, %zu from the HD download)\n",
                         found, g_root.c_str(), g_pack.custom(), found - g_pack.custom());
        } else {
            std::fprintf(stderr, "hd: no HD texture pack in %s; original textures stay\n", g_root.c_str());
        }
        std::fflush(stderr);
    }
    return true;
}

bool ammo_available(int slot) {
    return g_current && slot >= 0 && slot < kAmmoSlots && kAmmo[slot].width && g_pack.find(kAmmo[slot].key);
}

bool ammo_icon(int slot, unsigned tile_width, unsigned tile_height, Image &image) {
    if (!ammo_available(slot)) return false;
    const AmmoArt &art = kAmmo[slot];
    if (tile_width < art.width || tile_height < art.height || tile_width > 64 || tile_height > 64) return false;
    Image source;
    if (!Pack::read(*g_pack.find(art.key), source)) return false;
    const Image sized = resample(source, art.width * kAmmoScale, art.height * kAmmoScale);
    if (sized.rgba.empty()) return false;
    image.width = tile_width * kAmmoScale;
    image.height = tile_height * kAmmoScale;
    image.rgba.assign(size_t(image.width) * image.height * 4, 0);
    for (unsigned y = 0; y < sized.height; y++) {
        std::copy(sized.rgba.begin() + size_t(y) * sized.width * 4, sized.rgba.begin() + size_t(y + 1) * sized.width * 4,
                  image.rgba.begin() + size_t(y) * image.width * 4);
    }
    return true;
}

Found lookup(const Tile &tile, Image &image, uint32_t &request) {
    if (!g_current || !g_pack.size()) return Found::none;
    Key key;
    if (!identify(tile, key)) return Found::none;
    const Entry *entry = g_pack.find(key);
    const bool trace = std::getenv("GE_HD_TRACE") != nullptr;
    if (entry == nullptr) {
        if (trace && g_reported.insert(key).second) {
            std::fprintf(stderr, "hd: miss %08X#%u#%u#%08X native=%ux%u\n", key.texture, key.format, key.size,
                         key.palette, tile.width, tile.height);
        }
        return Found::none;
    }
    if (entry->custom) {
        if (trace && g_reported.insert(key).second) {
            std::fprintf(stderr, "hd: custom %08X#%u#%u#%08X %ux%u from %s\n", key.texture, key.format, key.size,
                         key.palette, tile.width, tile.height, entry->file.filename().string().c_str());
        }
        Workers &w = workers();
        std::lock_guard<std::mutex> guard(w.lock);
        if (!w.started) {
            w.started = true;
            for (int i = 0; i < kWorkers; i++) std::thread(work).detach();
        }
        request = ++g_next_request ? g_next_request : ++g_next_request;  /* 0 means none */
        w.jobs.push_back({request, g_generation.load(), key, *entry, tile.width, tile.height});
        w.wake.notify_one();
        return Found::later;
    }
    if (!usable(*entry, tile.width, tile.height, image)) {
        if (g_reported.insert(key).second) {
            std::fprintf(stderr, "hd: unusable image for %08X in %s; original kept\n", key.texture,
                         entry->file.string().c_str());
        }
        return Found::none;
    }
    if (trace && g_reported.insert(key).second) {
        std::fprintf(stderr, "hd: match %08X#%u#%u#%08X %ux%u -> %ux%u\n", key.texture, key.format, key.size,
                     key.palette, tile.width, tile.height, image.width, image.height);
    }
    return Found::now;
}

void kept(const Tile &tile) {
    if (!g_current || !std::getenv("GE_HD_TRACE")) return;
    Key key;
    if (!identify(tile, key)) return;
    if (!g_reported.insert(key).second) return;
    const Entry *entry = g_pack.find(key);
    std::fprintf(stderr, "hd: kept %08X#%u#%u#%08X native=%ux%u (first-person weapon or hands)%s%s\n", key.texture,
                 key.format, key.size, key.palette, tile.width, tile.height, entry ? ", in " : "",
                 entry ? entry->file.filename().string().c_str() : "");
}

bool finished(uint32_t &request, Image &image) {
    Workers &w = workers();
    std::lock_guard<std::mutex> guard(w.lock);
    while (!w.done.empty()) {
        Done done = std::move(w.done.front());
        w.done.pop_front();
        if (done.generation != g_generation.load()) continue;
        request = done.request;
        image = std::move(done.image);
        return true;
    }
    return false;
}
}  // namespace hd_textures
